   119	fn is_utc_millis_shape(value: &str) -> bool {
   120	    let bytes = value.as_bytes();
   121	    bytes.len() == 24
   122	        && value.is_ascii()
   123	        && bytes.iter().enumerate().all(|(index, byte)| match index {
   124	            4 | 7 => *byte == b'-',
   125	            10 => *byte == b'T',
   126	            13 | 16 => *byte == b':',
   127	            19 => *byte == b'.',
   128	            23 => *byte == b'Z',
   129	            _ => byte.is_ascii_digit(),
   130	        })
   131	}
