   199	struct ReplacementMarker {
   200	    staged: FileIdentity,
   201	    destination: Option<FileIdentity>,
   202	}
   203	
   204	impl ReplacementMarker {
   205	    fn encode(self) -> String {
   206	        format!(
   207	            "version=1\n{}{}",
   208	            self.staged.marker(),
   209	            self.destination
   210	                .map(FileIdentity::marker)
   211	                .unwrap_or_else(|| "none\n".into())
   212	        )
   213	    }
   214	
   215	    fn parse(value: &[u8]) -> io::Result<Self> {
   216	        let text = std::str::from_utf8(value).map_err(|_| invalid_data("invalid_commit_marker"))?;
   217	        let mut lines = text.lines();
   218	        if lines.next() != Some("version=1") {
   219	            return Err(invalid_data("invalid_commit_marker"));
   220	        }
   221	        let staged = FileIdentity::parse_marker(
   222	            lines
   223	                .next()
   224	                .ok_or_else(|| invalid_data("invalid_commit_marker"))?,
   225	        )?;
   226	        let destination = lines
   227	            .next()
   228	            .ok_or_else(|| invalid_data("invalid_commit_marker"))?;
   229	        if lines.next().is_some() {
   230	            return Err(invalid_data("invalid_commit_marker"));
   231	        }
   232	        let destination = if destination == "none" {
   233	            None
   234	        } else {
   235	            Some(FileIdentity::parse_marker(destination)?)
   236	        };
   237	        Ok(Self {
   238	            staged,
   239	            destination,
   240	        })
   241	    }
   242	}
