   244	impl SshForwardStore {
   245	    pub(crate) fn open(app_config_dir: &Path) -> io::Result<Self> {
   246	        let app_config = Arc::new(open_root(app_config_dir)?);
   247	        let root = Arc::new(open_or_create_relative_directory_no_delete(
   248	            &app_config,
   249	            STORE_ROOT,
   250	        )?);
   251	        let root_identity = file_identity(&root)?;
   252	        let scopes = Arc::new(open_or_create_relative_directory_no_delete(
   253	            &root,
   254	            SCOPES_DIRECTORY,
   255	        )?);
   256	        let scopes_identity = file_identity(&scopes)?;
   257	        let lock_file = Arc::new(open_exclusive_relative_file(&root, LOCK_FILE)?);
   258	        let store = Self {
   259	            app_config,
   260	            root,
   261	            root_identity,
   262	            scopes,
   263	            scopes_identity,
   264	            lock_file,
   265	            write_gate: Arc::new(Mutex::new(())),
   266	            desktop_instance_id: Mutex::new(None),
   267	        };
   268	        {
   269	            let _gate = lock(&store.write_gate)?;
   270	            let _file_lock = acquire_file_lock(&store.lock_file)?;
   271	            store.ensure_current()?;
   272	            recover_identity_artifacts(&store.root)?;
   273	            recover_storage_artifacts(&store.scopes)?;
   274	            recover_trust_repair_artifacts(&store.root)?;
   275	        }
   276	        Ok(store)
   277	    }
