   279	    /// Acquires the cross-process runtime lease used by the live manager and
   280	    /// stopped-app maintenance mode. Phase 04 should retain this guard for
   281	    /// the full manager runtime, not just for individual store operations.
   282	    pub(crate) fn acquire_feature_runtime_lease(&self) -> io::Result<FeatureRuntimeLease> {
   283	        self.ensure_current()?;
   284	        let handle = open_exclusive_relative_file(&self.root, RUNTIME_LOCK_FILE)?;
   285	        let offset = 0;
   286	        let guard =
   287	            acquire_file_lock_at(&handle, offset).map_err(|_| invalid_data("runtime_active"))?;
   288	        std::mem::forget(guard);
   289	        Ok(FeatureRuntimeLease {
   290	            handle,
   291	            offset,
   292	            root: self.root.try_clone()?,
   293	        })
   294	    }
