   340	    /// Returns all scope directories whose retained metadata proves their UUID/hash pair.
   341	    pub(crate) fn enumerate_scopes(&self) -> io::Result<Vec<ScopeStore>> {
   342	        let _gate = lock(&self.write_gate)?;
   343	        let _file_lock = acquire_file_lock(&self.lock_file)?;
   344	        self.ensure_current()?;
