} from "@dam-hopper/ui/lib/ssh-forward-host";

export const NATIVE_SSH_FORWARD_COMMANDS = {
  openClient: "ssh_forward_open_client", activateScope: "ssh_forward_activate_scope", snapshot: "ssh_forward_snapshot",
  createProfile: "ssh_forward_create_profile", updateProfile: "ssh_forward_update_profile", deleteProfile: "ssh_forward_delete_profile",
  start: "ssh_forward_start", stop: "ssh_forward_stop", restart: "ssh_forward_restart", listKeys: "ssh_forward_list_keys",
  approveHost: "ssh_forward_approve_host", purgeScope: "ssh_forward_purge_scope",
} as const satisfies Record<Exclude<keyof SshForwardHost, "subscribe" | "dispose">, string>;

const IPC_UNAVAILABLE: SshForwardError = { code: "IPC_UNAVAILABLE", message: "Native SSH forwarding is temporarily unavailable.", retryable: true };
const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
const FINGERPRINT = /^SHA256:[A-Za-z0-9+/]{43}$/;
const STATES = new Set(["stopped", "starting", "running", "reconnecting", "stopping", "failed"]);
const DISPOSITIONS = new Set(["notRequested", "queued", "started", "skippedActiveLimit"]);
const REASONS = new Set(["profilesChanged", "runtimeChanged", "trustChanged"]);
const ALGORITHMS = new Set(["ssh-ed25519", "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521"]);

function record(value: unknown): Record<string, unknown> | null { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }
function exactKeys(value: Record<string, unknown>, required: readonly string[], optional: readonly string[] = []): boolean {
