  const raw = record(value); return !!raw && exactKeys(raw, ["desktopInstanceId", "managerSessionId", "clientEpoch"]) && uuid(raw.desktopInstanceId) && uuid(raw.managerSessionId) && counter(raw.clientEpoch);
}
