function validSnapshot(value: unknown, context: DesktopClientContext, token: WireCounter, scopeId: string, scopeGeneration: WireCounter): value is SshForwardSnapshot {
  const raw = record(value);
  if (!raw || !exactKeys(raw, ["context", "scopeId", "activationToken", "scopeGeneration", "profilesRevision", "trustRevision", "profiles", "runtimes", "hostKeyChallenges"]) || !validContext(raw.context) || !sameContext(raw.context, context) || raw.scopeId !== scopeId || raw.activationToken !== token || raw.scopeGeneration !== scopeGeneration || !counter(raw.profilesRevision) || !counter(raw.trustRevision) || !Array.isArray(raw.profiles) || !Array.isArray(raw.runtimes) || !Array.isArray(raw.hostKeyChallenges) || !raw.profiles.every(validProfile)) return false;
  return raw.runtimes.every((runtime) => { const item = record(runtime); return !!item && exactKeys(item, ["profileId", "generation", "state", "bindHost", "localPort", "retryAttempt", "activeChannels", "autoStartDisposition", "stateChangedAt"], ["startedAt", "errorCode"]) && uuid(item.profileId) && counter(item.generation) && typeof item.state === "string" && STATES.has(item.state) && item.bindHost === "127.0.0.1" && port(item.localPort) && typeof item.retryAttempt === "number" && Number.isInteger(item.retryAttempt) && item.retryAttempt >= 0 && item.retryAttempt <= 5 && typeof item.activeChannels === "number" && Number.isInteger(item.activeChannels) && item.activeChannels >= 0 && item.activeChannels <= 65535 && typeof item.autoStartDisposition === "string" && DISPOSITIONS.has(item.autoStartDisposition) && validTimestamp(item.stateChangedAt) && (item.startedAt === undefined || validTimestamp(item.startedAt)) && (item.errorCode === undefined || !!parseSshForwardError({ code: item.errorCode, message: "", retryable: false })); }) && raw.hostKeyChallenges.every((challenge) => { const item = record(challenge); return !!item && exactKeys(item, ["challengeId", "profileId", "scopeId", "generation", "sshHost", "sshPort", "algorithm", "fingerprint", "expiresAt"]) && uuid(item.challengeId) && uuid(item.profileId) && item.scopeId === scopeId && counter(item.generation) && canonicalHost(item.sshHost) && port(item.sshPort) && typeof item.algorithm === "string" && ALGORITHMS.has(item.algorithm) && fingerprint(item.fingerprint) && validTimestamp(item.expiresAt); });
