  const raw = record(value); return !!raw && exactKeys(raw, ["context", "scopeId", "scopeGeneration", "keys"]) && validContext(raw.context) && sameContext(raw.context, context) && raw.scopeId === scopeId && raw.scopeGeneration === scopeGeneration && Array.isArray(raw.keys) && raw.keys.every((key) => { const item = record(key); return !!item && exactKeys(item, ["keyId", "label", "algorithm", "fingerprint"]) && safeAscii(item.keyId, 128) && boundedText(item.label, 255) && typeof item.algorithm === "string" && ALGORITHMS.has(item.algorithm) && fingerprint(item.fingerprint); });
