  private context: DesktopClientContext | null = null; private activationToken: WireCounter | null = null; private scopeId: string | null = null; private scopeGeneration: WireCounter | null = null; private snapshotState: SshForwardSnapshot | null = null; private hintFreshness: [WireCounter, WireCounter, WireCounter] | null = null; private knownScopes: KnownScopesInput = { status: "unavailable" }; private operation = 0; private reopening = false; private snapshotInFlight = false; private snapshotTrailing = false; private readonly listeners = new Set<(event: SshForwardHostEvent) => void>(); private unlisten: UnlistenFn | null = null; private listening: Promise<void> | null = null; private disposed = false;

