  async activateScope(scopeId: string | null): Promise<ScopeActivation> { if (!this.context || !this.activationToken || (scopeId !== null && !uuid(scopeId))) throw IPC_UNAVAILABLE; const token = incrementWireCounter(this.activationToken); if (!token) throw { ...IPC_UNAVAILABLE, code: "COUNTER_EXHAUSTED" as const }; const operation = ++this.operation, context = this.context; this.activationToken = token; this.scopeId = scopeId; this.snapshotState = null; const result = await this.invoke<ScopeActivation>(NATIVE_SSH_FORWARD_COMMANDS.activateScope, { input: { context, activationToken: token, scopeId } }); if (!this.validActivation(result, context, token, scopeId)) throw IPC_UNAVAILABLE; if (!this.isCurrent(context, token, scopeId, operation)) throw { ...IPC_UNAVAILABLE, code: "ACTIVATION_SUPERSEDED" as const, message: "Activation was superseded by a newer scope request.", retryable: true }; this.scopeGeneration = result.scopeGeneration; this.acceptSnapshot(result.snapshot); return result; }
  snapshot(): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.snapshot, {}, true); }
  createProfile(profile: SshForwardProfile): Promise<SshForwardSnapshot> { return this.command(NATIVE_SSH_FORWARD_COMMANDS.createProfile, { profile, expectedProfilesRevision: this.requireSnapshot().profilesRevision }); }
