     1	//! One bounded disposal owner for SSH forwarding and Browser Debug.
     2	
     3	use std::{
     4	    sync::{
     5	        atomic::{AtomicU8, Ordering},
     6	        Arc,
     7	    },
     8	    time::{Duration, Instant},
     9	};
    10	
    11	use tauri::AppHandle;
    12	
    13	use crate::{
    14	    browser_debug::controller::BrowserDebugController, ssh_forward::manager::SshForwardManager,
    15	};
    16	
    17	const RUNNING: u8 = 0;
    18	const DISPOSING: u8 = 1;
    19	const DISPOSED: u8 = 2;
    20	const SHUTDOWN_GRACE: Duration = Duration::from_secs(5);
    21	
    22	pub(crate) struct NativeShutdownCoordinator {
    23	    state: AtomicU8,
    24	    manager: Arc<SshForwardManager>,
    25	    browser_debug: Arc<BrowserDebugController>,
    26	}
    27	
    28	impl NativeShutdownCoordinator {
    29	    pub(crate) fn new(
    30	        manager: Arc<SshForwardManager>,
    31	        browser_debug: Arc<BrowserDebugController>,
    32	    ) -> Self {
    33	        Self {
    34	            state: AtomicU8::new(RUNNING),
    35	            manager,
    36	            browser_debug,
    37	        }
    38	    }
    39	
    40	    #[allow(dead_code)]
    41	    pub(crate) fn is_disposed(&self) -> bool {
    42	        self.state.load(Ordering::Acquire) == DISPOSED
    43	    }
    44	
    45	    pub(crate) fn should_prevent_exit(&self) -> bool {
    46	        self.state.load(Ordering::Acquire) != DISPOSED
    47	    }
    48	
    49	    pub(crate) fn trigger(self: &Arc<Self>, app: AppHandle) {
    50	        if self
    51	            .state
    52	            .compare_exchange(RUNNING, DISPOSING, Ordering::AcqRel, Ordering::Acquire)
    53	            .is_err()
    54	        {
    55	            return;
    56	        }
    57	        let coordinator = Arc::clone(self);
    58	        tauri::async_runtime::spawn(async move {
    59	            let deadline = Instant::now() + SHUTDOWN_GRACE;
    60	            let manager = Arc::clone(&coordinator.manager);
    61	            let browser_debug = Arc::clone(&coordinator.browser_debug);
    62	            let cleanup_app = app.clone();
    63	            let cleanup = tauri::async_runtime::spawn_blocking(move || {
    64	                browser_debug.cleanup_on_main_close(&cleanup_app);
    65	            });
    66	            let manager_dispose = async {
    67	                let remaining = deadline.saturating_duration_since(Instant::now());
    68	                let _ = tokio::time::timeout(remaining, manager.dispose()).await;
    69	            };
    70	            let browser_cleanup = async {
    71	                let remaining = deadline.saturating_duration_since(Instant::now());
    72	                let _ = tokio::time::timeout(remaining, cleanup).await;
    73	            };
    74	            tokio::join!(manager_dispose, browser_cleanup);
    75	            coordinator.manager.force_close();
    76	            coordinator.state.store(DISPOSED, Ordering::Release);
    77	            app.exit(0);
    78	        });
    79	    }
    80	
    81	    pub(crate) fn force_close_now(&self) {
    82	        self.manager.force_close();
    83	        self.state.store(DISPOSED, Ordering::Release);
    84	    }
    85	}
    86	
    87	#[cfg(test)]
    88	mod tests {
    89	    use super::{DISPOSED, DISPOSING, RUNNING, SHUTDOWN_GRACE};
    90	    use std::time::Duration;
    91	
    92	    #[test]
    93	    fn shutdown_contract_is_single_owner_and_bounded() {
    94	        assert_eq!(RUNNING, 0);
    95	        assert_eq!(DISPOSING, 1);
    96	        assert_eq!(DISPOSED, 2);
    97	        assert_eq!(SHUTDOWN_GRACE, Duration::from_secs(5));
    98	    }
    99	
