  1359	    async fn reconnect_session(
  1360	        self: &Arc<Self>,
  1361	        listener: &TcpListener,
  1362	        endpoint: &SshEndpoint,
  1363	        profile: &SshForwardProfile,
  1364	        trust: &StoredTrust,
  1365	        stop_rx: &mut oneshot::Receiver<Instant>,
  1366	    ) -> ReconnectResult {
  1367	        if !profile.reconnect.enabled {
  1368	            return ReconnectResult::Failed(SshForwardErrorCode::SshConnectFailed);
  1369	        }
  1370	        for attempt in 1..=profile.reconnect.max_attempts {
  1371	            let backoff = sleep(Duration::from_secs(u64::from(attempt.min(30))));
  1372	            tokio::pin!(backoff);
  1373	            loop {
  1374	                tokio::select! {
  1375	                    stopped = &mut *stop_rx => {
  1376	                        return ReconnectResult::Cancelled(
  1377	                            stopped.unwrap_or_else(|_| Instant::now() + WORKER_SHUTDOWN_GRACE),
  1378	                        );
  1379	                    }
  1380	                    accepted = listener.accept() => {
  1381	                        let Ok((socket, _)) = accepted else {
  1382	                            return ReconnectResult::Failed(SshForwardErrorCode::BindFailed);
  1383	                        };
  1384	                        drop(socket);
  1385	                    }
  1386	                    _ = &mut backoff => break,
  1387	                }
  1388	            }
  1389	
  1390	            let manager = Arc::clone(self);
  1391	            let final_attempt = attempt == profile.reconnect.max_attempts;
  1392	            let endpoint = endpoint.clone();
  1393	            let profile = profile.clone();
  1394	            let trust = trust.clone();
  1395	            let mut connect =
  1396	                tokio::spawn(
  1397	                    async move { manager.connect_session(&endpoint, &profile, &trust).await },
  1398	                );
  1399	            loop {
  1400	                tokio::select! {
  1401	                    stopped = &mut *stop_rx => {
  1402	                        connect.abort();
  1403	                        let _ = connect.await;
  1404	                        return ReconnectResult::Cancelled(
  1405	                            stopped.unwrap_or_else(|_| Instant::now() + WORKER_SHUTDOWN_GRACE),
  1406	                        );
  1407	                    }
  1408	                    accepted = listener.accept() => {
  1409	                        let Ok((socket, _)) = accepted else {
  1410	                            connect.abort();
  1411	                            let _ = connect.await;
  1412	                            return ReconnectResult::Failed(SshForwardErrorCode::BindFailed);
  1413	                        };
  1414	                        // Keep the bind reservation but reject admission while SSH is down.
  1415	                        drop(socket);
  1416	                    }
  1417	                    result = &mut connect => match result {
  1418	                        Ok(Ok(session)) => return ReconnectResult::Connected(session),
  1419	                        Ok(Err(error)) if final_attempt => {
  1420	                            return ReconnectResult::Failed(error.error_code());
  1421	                        }
  1422	                        Ok(Err(_)) => break,
  1423	                        Err(_) => return ReconnectResult::Failed(SshForwardErrorCode::SshConnectFailed),
  1424	                    }
  1425	                }
  1426	            }
  1427	        }
  1428	        ReconnectResult::Failed(SshForwardErrorCode::SshConnectFailed)
  1429	    }
