  1327	                            if !self.mark_running(&profile_id, generation).await {
  1328	                                if let Some(next) = session.take() {
  1329	                                    let _ = timeout(WORKER_SHUTDOWN_GRACE, next.close()).await;
  1330	                                }
  1331	                                break;
  1332	                            }
  1333	                        }
  1334	                        ReconnectResult::Cancelled(deadline) => {
  1335	                            stop_deadline = Some(deadline);
  1336	                            break;
  1337	                        }
  1338	                        ReconnectResult::Failed(code) => {
  1339	                            self.fail_runtime(&profile_id, generation, code).await;
  1340	                            break;
  1341	                        }
  1342	                    }
  1343	                }
  1344	            }
  1345	        }
  1346	        // Drop the listener before waiting for child cleanup so Stop/scope switch/exit
  1347	        // makes the loopback port unreachable immediately.
  1348	        drop(listener);
  1349	        let deadline = stop_deadline.unwrap_or_else(|| Instant::now() + WORKER_SHUTDOWN_GRACE);
  1350	        abort_channel_tasks(&mut channel_tasks, deadline).await;
  1351	        if let Some(session) = session {
  1352	            let remaining = deadline.saturating_duration_since(Instant::now());
  1353	            if !remaining.is_zero() {
  1354	                let _ = timeout(remaining, session.close()).await;
  1355	            }
  1356	        }
  1357	    }
