   807	                .await;
   808	        }
   809	        self.close_workers(retired_workers).await;
   810	        self.abort_and_remove_handle(&input.profile_id);
   811	        let registration = {
   812	            let _admission = self.intent_admission_gate.lock().await;
   813	            let result = self
   814	                .checked_scope(
   815	                    &input.context,
   816	                    input.activation_token,
   817	                    &input.scope_id,
   818	                    input.scope_generation,
   819	                )
