   835	                let scope_id = input.scope_id.clone();
   836	                let profile_id = input.profile_id.clone();
   837	                let token = input.activation_token;
   838	                let scope_generation = input.scope_generation;
   839	                let active_channels = self
   840	                    .runtimes
   841	                    .lock()
   842	                    .await
   843	                    .get(&input.profile_id)
   844	                    .map(|runtime| Arc::clone(&runtime.active_channels));
   845	                let task = tokio::spawn(async move {
   846	                    manager
   847	                        .run_profile(
   848	                            profile,
   849	                            trust,
   850	                            context,
   851	                            token,
